+            });
+        },
+    });
+
+    useEffect(() => {
+        if (isConnected && app) {
+            setHostContext(displayContext(app.getHostContext()));
+        }
+    }, [app, isConnected]);
+
+    const adapter = useMemo(
+        () => (app && isConnected ? createFixtureAdapter(app) : null),
+        [app, isConnected],
+    );
